<?php $resumoImportacao = $plano['resumo']; $acoesImportacao = ['novo' => 'Novo cadastro', 'vinculo' => 'Novo vínculo', 'ignorado' => 'Já existente', 'erro' => 'Corrigir']; ?>
<main class="lic-import">
<?= view('licenciandos/import/cabecalho', ['etapaImportacao' => 2]) ?>
<section class="import-card import-review-summary"><h2><i class="bx bx-check-shield" aria-hidden="true"></i> Confira antes de importar</h2><p>Ano de referência: <strong><?= esc($plano['periodo']) ?></strong>. Nenhum registro foi gravado nesta etapa.</p><div class="import-summary-grid"><?php foreach (['registros' => 'Registros no arquivo', 'novos_licenciandos' => 'Novos licenciandos', 'novos_vinculos' => 'Novos vínculos', 'ignorados' => 'Já existentes', 'erros' => 'Registros com erro'] as $key => $label): ?><div><span><?= esc($label) ?></span><strong><?= number_format($resumoImportacao[$key], 0, ',', '.') ?></strong></div><?php endforeach ?></div></section>
<?php if ($resumoImportacao['erros']): ?><section class="import-card import-errors"><h2><i class="bx bx-error" aria-hidden="true"></i> Corrija o arquivo e envie novamente</h2><ul><?php foreach ($plano['linhas'] as $linha): if ($linha['acao'] !== 'erro') continue; ?><li><strong>Linha <?= (int) $linha['linha'] ?>:</strong> <?= esc($linha['mensagem']) ?></li><?php endforeach ?></ul></section><?php endif ?>
<section class="import-card import-review-table"><h2><i class="bx bx-table" aria-hidden="true"></i> Registros para conferência</h2><p class="import-caption">Prévia dos primeiros <?= min(100, count($plano['linhas'])) ?> registros. A conferência e os totais consideram o arquivo inteiro.</p><div class="import-table-scroll"><table class="import-table"><thead><tr><th>Linha</th><th>Nome</th><th>DRE</th><th>Universidade</th><th>Setor</th><th>Ação prevista</th><th>Detalhes</th></tr></thead><tbody><?php foreach (array_slice($plano['linhas'], 0, 100) as $linha): ?><tr><td><?= (int) $linha['linha'] ?></td><td><?= esc($linha['dados']['nome_completo']) ?></td><td><?= esc($linha['dados']['dre']) ?></td><td><?= esc($linha['dados']['universidade']) ?></td><td><?= esc($linha['dados']['setor']) ?></td><td><span class="import-status import-status-<?= esc($linha['acao']) ?>"><?= esc($acoesImportacao[$linha['acao']]) ?></span></td><td><?= esc($linha['mensagem']) ?></td></tr><?php endforeach ?></tbody></table></div></section>
<?php if (!$resumoImportacao['erros'] && !$resumoImportacao['novos_vinculos']): ?><p class="import-caption">Todos os vínculos já estão cadastrados. Nenhuma gravação é necessária.</p><?php endif ?>
<div class="import-actions"><a class="import-cancel" href="<?= base_url('licenciandos/importar') ?>">Escolher outro arquivo</a><form action="<?= base_url('licenciandos/importar/confirmar') ?>" method="post"><?= csrf_field() ?><input type="hidden" name="token_importacao" value="<?= esc($tokenImportacao ?? '') ?>"><button type="submit" class="import-primary" <?= $tokenImportacao ? '' : 'disabled' ?>><i class="bx bx-check" aria-hidden="true"></i> Confirmar importação</button></form></div>
</main>
